#[inline]
fn destack_display_monitor_modes_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<DisplayMode>,
    handle: resource::DisplayHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.trace().run_binding_without_context(
        DISPLAY_MONITOR_MODES,
        binding.replay_payload_for(DISPLAY_MONITOR_MODES)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_display_monitor_modes(binding, out, handle)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_display_monitor_modes(binding, out, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeSlice<DisplayMode> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded_width = result_recorded_item.width;
                    let result_recorded_item_recorded_height = result_recorded_item.height;
                    let result_recorded_item_recorded_refresh_milli_hz =
                        result_recorded_item.refresh_milli_hz;
                    let result_recorded_item_recorded_format = result_recorded_item.format;
                    let result_recorded_item_recorded_bit_depth = result_recorded_item.bit_depth;
                    let result_recorded_item_recorded = DisplayMode {
                        width: result_recorded_item_recorded_width,
                        height: result_recorded_item_recorded_height,
                        refresh_milli_hz: result_recorded_item_recorded_refresh_milli_hz,
                        format: result_recorded_item_recorded_format,
                        bit_depth: result_recorded_item_recorded_bit_depth,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DisplayMonitorModesReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DisplayMonitorModesReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native =
                        binding.store_slice_with(value.len(), |value_native_values| {
                            for value_native_item in value {
                                let value_native_decoded_width = value_native_item.width;
                                let value_native_decoded_height = value_native_item.height;
                                let value_native_decoded_refresh_milli_hz =
                                    value_native_item.refresh_milli_hz;
                                let value_native_decoded_format = value_native_item.format;
                                let value_native_decoded_bit_depth = value_native_item.bit_depth;
                                let value_native_decoded = DisplayMode {
                                    width: value_native_decoded_width,
                                    height: value_native_decoded_height,
                                    refresh_milli_hz: value_native_decoded_refresh_milli_hz,
                                    format: value_native_decoded_format,
                                    bit_depth: value_native_decoded_bit_depth,
                                };
                                value_native_values.push(value_native_decoded);
                            }
                            Ok(())
                        })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

